"category_id"><option value="">Uncategorized</option><?php foreach($receiptCategories as $category):?><option value="<?=(int)$category['id']?>"><?=manage_e($category['category_name'])?></option><?php endforeach;?></select></label><?php if(!$isOwnerCard):?><label class="manage-manual-receipt-found"><span>Receipt Found</span><input type="checkbox" name="receipt_found" value="1"></label><?php endif;?><label class="manage-manual-notes">Notes<textarea name="notes" rows="2" maxlength="5000" placeholder="Optional notes"></textarea></label><div class="manage-manual-transaction-actions"><button type="button" class="manage-button" data-cancel-manual-transaction>Cancel</button><button type="submit" class="manage-button primary"><i class="fa-solid fa-floppy-disk" aria-hidden="true"></i> Save Entry</button></div></form><?php endif;?><div class="manage-breakdown-table-wrap"><table class="manage-breakdown-table"><thead><tr><th>Date</th><th>Type</th><th>Description</th><th>Amount</th><th>Category</th><?php if($isOwnerCard):?><th>Receipt #</th><?php else:?><th>Receipt Found</th><?php endif;?><th>Notes</th></tr></thead><tbody><?php foreach($card['items'] as $itemIndex=>$transaction):?><tr data-transaction-id="<?=(int)$transaction['id']?>"><td><?=manage_e(date('M j, Y',strtotime((string)$transaction['transaction_date'])))?></td><td><span class="manage-transaction-type <?=manage_e($transaction['transaction_type']??'charge')?>"><?=manage_e(ucfirst($transaction['transaction_type']??'charge'))?></span></td><td><?=($itemIndex+1).' - '.manage_e($transaction['description'])?></td><td class="manage-breakdown-amount<?=((float)$transaction['amount']<0)?' credit':''?>">$<?=number_format((float)$transaction['amount'],2)?></td><td><select data-transaction-category <?=$receiptBreakdownLocked?'disabled':''?>><option value="">Uncategorized</option><?php foreach($receiptCategories as $category):?><option value="<?=(int)$category['id']?>" <?=((int)($transaction['category_id']??0)===(int)$category['id']