<section class="manage-panel manage-receipt-finalize"><div class="manage-finalize-heading"><div><h2>Finalize</h2><p><?=manage_e($months[$month].' '.$year)?> totals grouped by the global receipt categories.</p></div></div><div class="manage-category-total-grid"><?php foreach($categoryTotals as $categoryName=>$categoryTotal):?><article class="<?=$categoryName==='UNCATEGORIZED'?'uncategorized':''?>" data-category-total="<?=manage_e($categoryName)?>"><span><?=manage_e($categoryName)?></span><strong>$<?=number_format($categoryTotal,2)?></strong></article><?php endforeach;?></div><div class="manage-finalize-grand-total"><span>Statement Net Total</span><strong>$<?=number_format($breakdownTotal,2)?></strong></div><?php if(manage_is_admin())manage_render_cpa_delivery_history($cpaDeliveries,$year,$month,$paymentRemaining,$uncategorizedTransactionCount,count($transactions));?><?php if(manage_is_admin()):?><section class="manage-manual-payments"><div><h3>Payments</h3></div><?php if(manage_receipt_payments_schema_ready()):?><div class="manage-payment-reconciliation"><article><span>Statement Balance</span><strong>$<?=number_format($breakdownTotal,2)?></strong></article><article><span>Payments</span><strong>$<?=number_format($paymentTotal,2)?></strong></article><article class="<?=abs($paymentRemaining)<0.005?'balanced':'remaining'?>"><span>Remaining Balance</span><strong>$<?=number_format($paymentRemaining,2)?></strong></article></div><h4>Submitted Payments</h4><div class="manage-payment-list"><?php foreach($payments as $payment):?><article data-payment-id="<?=(int)$payment['id']?>"><span><?=manage_e(date('M j, Y',strtotime((string)$payment['payment_date'])))?></span><span><?=manage_e($payment['bank_account_paid_from'])?></span><strong>$<?=number_format((float)$payment['amount_paid'],2)?></strong><button type="button" class="manage-file-delete" data-payment-delete aria-label="Delete payment"><i class="fa-solid fa-trash"></i></button></article><?php endforeach;?><?php if(!$payments):?><p class="manage-empty-files">No manual payments have been added.</p><?php endif;?></div><h4>Add Payment</h4><form class="manage-payment-entry-form" data-payment-form><label>Date<input type="date" name="payment_date" required value="<?=manage_e(date('Y-m-d'))?>"></label><label>Bank Account Paid From<?=$propertyBankAccountNumber!==''?' ('.manage_e($propertyBankAccountNumber).')':''?><input name="bank_account_paid_from" maxlength="190" required placeholder="Account name or last four"></label><label>Amount Paid<span class="manage-money-input"><span>$</span><input name="amount_paid" inputmode="decimal" required placeholder="0.00"></span></label><button class="manage-button primary">Add Payment</button></form><?php else:?><div class="manage-alert error">Run the Management Properties upgrade to enable manual payment entries.</div><?php endif;?><article class="manage-receipt-upload-card manage-payment-upload-card" data-category="payment"><label class="manage-file-upload manage-file-drop-zone" data-receipt-drop><strong><i class="fa-solid fa-file-arrow-up"></i> Upload Payment PDFs</strong><span>Drag and drop one or more payment PDFs here, or click to browse.</span><span class="manage-upload-selection">No files selected</span><input type="file" multiple data-receipt-upload accept=".pdf,application/pdf"></label><div class="manage-existing-files" data-receipt-files><strong>Payment Files</strong><?php foreach($filesByCategory['payment'] as $file):?><span class="manage-file-item" data-file-id="<?=(int)$file['id']?>"><a href="receipt_file.php?id=<?=(int)$file['id']?>"><i class="fa-solid fa-paperclip"></i> <?=manage_e($file['original_name'])?></a><button type="button" class="manage-file-delete" data-file-id="<?=(int)$file['id']?>" aria-label="Delete <?=manage_e($file['original_name'])?>"><i class="fa-solid fa-trash"></i></button></span><?php endforeach;?><?php if(!$filesByCategory['payment']):?><span class="manage-empty-files">No payment files have been uploaded.</span><?php endif;?></div></article></section><?php endif;?></section>
